-- Bootstrap 5 (tracker C7). Objects created by hand on the hosted production database and needed from 20261002152000_learning_rpc_context_hardening.sql on.
-- Each is created ONLY IF MISSING: on production nothing changes; on an empty database this supplies them. Generated by scripts/release/build_bootstrap.py.
begin;
set local check_function_bodies = off;

do $boot$ begin if to_regprocedure('public.qb_get_questions(text, text, integer)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_get_questions(p_subject_code text DEFAULT NULL::text, p_grade text DEFAULT NULL::text, p_limit integer DEFAULT 20)
 RETURNS TABLE(id uuid, external_question_id text, subject_code text, subject_name text, grade qb_grade, strand_no text, strand_name text, substrand_no text, substrand_name text, content_standard_code text, content_standard_text text, indicator_code text, indicator_text text, difficulty_code text, difficulty_label text, cognitive_level text, question_code text, question_text text, question_content jsonb, answer_type text, option_a text, option_b text, option_c text, option_d text, marks numeric, estimated_time_seconds integer, tags text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select
        q.id,
        q.external_question_id,

        q.subject_code,
        q.subject_name,
        q.grade,

        q.strand_no,
        q.strand_name,

        q.substrand_no,
        q.substrand_name,

        q.content_standard_code,
        q.content_standard_text,

        q.indicator_code,
        q.indicator_text,

        q.difficulty_code,
        q.difficulty_label,
        q.cognitive_level,

        q.question_code,

        q.question_text,
        q.question_content,

        q.answer_type,

        q.option_a,
        q.option_b,
        q.option_c,
        q.option_d,

        q.marks,
        q.estimated_time_seconds,

        q.tags
    from public.questions q
    where
        q.status = 'active' and auth.uid() is not null and public.qb_question_is_available(q)
        and (
            p_subject_code is null
            or q.subject_code = p_subject_code
        )
        and (
            p_grade is null
            or q.grade::text = p_grade
        )
    order by random()
    limit least(
        greatest(coalesce(p_limit, 20), 1),
        100
    );
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_my_results(integer)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_my_results(p_limit integer DEFAULT 50)
 RETURNS SETOF assessment_results
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

    select *
    from public.assessment_results
    where student_id =
        public.qb_current_student_id()

    order by
        submitted_at desc nulls last

    limit least(
        greatest(
            coalesce(p_limit,50),
            1
        ),
        200
    );

$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_normalize_text(text)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_normalize_text(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
    select upper(
        regexp_replace(
            trim(coalesce(p_value,'')),
            '\\s+',
            ' ',
            'g'
        )
    );
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_set_updated_at()') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    new.updated_at = now();
    return new;
end;
$function$
$qb_bootstrap$; end if; end $boot$;

commit;
